use super::*;
use serde_json::json;

fn store() -> Connection {
    let conn = bsc_sqlite_util::open_in_memory_db().expect("in-memory store");
    conn.execute_batch(SCHEMA).expect("schema");
    conn
}

fn rec(code: &str) -> Value {
    json!({ "id": "a.rs", "name": "a", "role": "algorithm", "tech": "rust", "code": code,
            "folder": "crates/x", "provides": "@/x/a" })
}

/// THE PROPERTY THE WHOLE DESIGN EXISTS FOR: a write cannot lose a version, because a write is an
/// INSERT and there is no current-record row to overwrite.
#[test]
fn every_write_keeps_the_version_before_it() {
    let c = store();
    assert_eq!(put(&c, "a.rs", &rec("v1"), "me", None, None).unwrap(), 1);
    assert_eq!(put(&c, "a.rs", &rec("v2"), "me", None, None).unwrap(), 2);
    assert_eq!(put(&c, "a.rs", &rec("v3"), "me", None, None).unwrap(), 3);
    assert_eq!(revs(&c, "a.rs").unwrap(), vec![3, 2, 1]);
    assert_eq!(get(&c, "a.rs").unwrap().unwrap()["code"], "v3", "current is the newest");
}

/// A version cannot be REWRITTEN either — replaying a rev is a constraint violation, not a clobber.
/// This is what the primary key buys on top of append-only.
#[test]
fn an_existing_rev_cannot_be_overwritten() {
    let c = store();
    put(&c, "a.rs", &rec("v1"), "me", None, None).unwrap();
    let forged = c.execute(
        "INSERT INTO record_revs (id, rev, json, at) VALUES ('a.rs', 1, '\"FORGED\"', 0)",
        [],
    );
    assert!(forged.is_err(), "rewriting rev 1 must be refused");
    assert_eq!(get(&c, "a.rs").unwrap().unwrap()["code"], "v1");
}

/// THE TRIGGER COMPARISON, pinned as a test rather than left in a comment.
///
/// A trigger-based history is real enforcement until someone runs `DROP TRIGGER` — measured on SQLite
/// 3.46, writes then continued with history silently frozen. Here there is nothing to drop: the schema
/// carries NO triggers, and history survives because a write has no way to touch an older row.
#[test]
fn the_guarantee_does_not_depend_on_a_trigger_that_could_be_dropped() {
    let c = store();
    let triggers: i64 = c
        .query_row("SELECT COUNT(*) FROM sqlite_master WHERE type = 'trigger'", [], |r| r.get(0))
        .unwrap();
    assert_eq!(triggers, 0, "history must not rest on a trigger — this schema has none to drop");

    put(&c, "a.rs", &rec("v1"), "me", None, None).unwrap();
    put(&c, "a.rs", &rec("v2"), "me", None, None).unwrap();
    assert_eq!(revs(&c, "a.rs").unwrap().len(), 2);
}

/// Reverting goes FORWARD. The old content comes back as a new rev, so the revert is itself a version
/// and the thing being recovered from is still on record.
#[test]
fn a_revert_appends_rather_than_rewrites() {
    let c = store();
    put(&c, "a.rs", &rec("good"), "me", None, None).unwrap();
    put(&c, "a.rs", &rec("BROKEN"), "me", None, None).unwrap();

    let back = revert(&c, "a.rs", 1, "me").unwrap();
    assert_eq!(back, 3, "the revert is a NEW rev, not a rewind");
    assert_eq!(get(&c, "a.rs").unwrap().unwrap()["code"], "good");
    assert_eq!(revs(&c, "a.rs").unwrap(), vec![3, 2, 1], "the broken rev is still there");

    // …and the revert can itself be reverted, which is the half that makes it safe to use in a panic.
    revert(&c, "a.rs", 2, "me").unwrap();
    assert_eq!(get(&c, "a.rs").unwrap().unwrap()["code"], "BROKEN");
}

/// A removal is a TOMBSTONE: no longer current, still recoverable. `impl remove` losing a record
/// permanently is the behaviour this replaces.
#[test]
fn a_removed_record_is_gone_from_current_and_still_recoverable() {
    let c = store();
    put(&c, "a.rs", &rec("v1"), "me", None, None).unwrap();
    remove(&c, "a.rs", "me", None).unwrap();
    assert!(get(&c, "a.rs").unwrap().is_none(), "a tombstoned record is not current");
    assert_eq!(revs(&c, "a.rs").unwrap(), vec![2, 1], "…and every version is still on disk");

    revert(&c, "a.rs", 1, "me").unwrap();
    assert_eq!(get(&c, "a.rs").unwrap().unwrap()["code"], "v1", "brought back from the dead");
}

/// Reverting TO a tombstone removes the record again — the symmetry matters, or "go back one version"
/// would mean something different depending on which version you landed on.
#[test]
fn reverting_to_a_tombstone_removes_the_record_again() {
    let c = store();
    put(&c, "a.rs", &rec("v1"), "me", None, None).unwrap();
    remove(&c, "a.rs", "me", None).unwrap();
    revert(&c, "a.rs", 1, "me").unwrap();
    revert(&c, "a.rs", 2, "me").unwrap(); // rev 2 was the tombstone
    assert!(get(&c, "a.rs").unwrap().is_none());
}

/// Optimistic concurrency, the same guard `impl set --if-version` already offers — and the reason it
/// matters more here: several sessions author this store at once.
#[test]
fn a_stale_write_is_refused_and_changes_nothing() {
    let c = store();
    put(&c, "a.rs", &rec("v1"), "me", None, None).unwrap();
    put(&c, "a.rs", &rec("v2"), "someone else", None, None).unwrap();

    let err = put(&c, "a.rs", &rec("stale"), "me", None, Some(1)).unwrap_err();
    assert!(err.contains("is at rev 2 in lane 'main', not 1"), "{err}");
    assert_eq!(get(&c, "a.rs").unwrap().unwrap()["code"], "v2", "the refused write changed nothing");
    assert_eq!(revs(&c, "a.rs").unwrap(), vec![2, 1], "…and left no version behind");
}

/// The projected columns are computed BY SQLITE from the body, so they cannot drift from it — which is
/// what lets a listing skip parsing bodies it is not going to show.
#[test]
fn the_projected_columns_follow_the_body_and_cannot_drift() {
    let c = store();
    put(&c, "a.rs", &rec("v1"), "me", None, None).unwrap();
    let (folder, provides): (String, String) = c
        .query_row("SELECT folder, provides FROM records WHERE id = 'a.rs'", [], |r| Ok((r.get(0)?, r.get(1)?)))
        .unwrap();
    assert_eq!(folder, "crates/x");
    assert_eq!(provides, "@/x/a");

    // Move the record's folder; the column follows without anyone maintaining it.
    let mut moved = rec("v2");
    moved["folder"] = json!("crates/y");
    put(&c, "a.rs", &moved, "me", None, None).unwrap();
    let folder: String = c.query_row("SELECT folder FROM records WHERE id = 'a.rs'", [], |r| r.get(0)).unwrap();
    assert_eq!(folder, "crates/y");
}

/// `records` must show exactly one row per live id — the head — and nothing for a tombstoned one.
#[test]
fn the_current_view_is_one_row_per_live_record() {
    let c = store();
    for id in ["a.rs", "b.rs", "c.rs"] {
        let mut r = rec("v1");
        r["id"] = json!(id);
        put(&c, id, &r, "me", None, None).unwrap();
        put(&c, id, &r, "me", None, None).unwrap(); // a second rev each
    }
    remove(&c, "c.rs", "me", None).unwrap();
    let live: i64 = c.query_row("SELECT COUNT(*) FROM records", [], |r| r.get(0)).unwrap();
    let total: i64 = c.query_row("SELECT COUNT(*) FROM record_revs", [], |r| r.get(0)).unwrap();
    assert_eq!(live, 2, "two live records");
    assert_eq!(total, 7, "…across seven versions, all retained");
}

mod import_tests {
    use super::*;
    use crate::import::{body_of, import, import_edges, legacy_history, RUNTIME_LANE};

    fn r(id: &str, code: &str) -> Value {
        json!({ "id": id, "name": id, "code": code, "tech": "rust" })
    }

    /// An edge fixture — the relationship tier's shape.
    fn e(id: &str, members: &[&str]) -> Value {
        json!({ "id": id, "members": members })
    }

    /// The two stores disagree on 305 ids. Neither is discarded: the runtime body goes in first and the
    /// COMMITTED body second, so the committed copy is current and the runtime one is one `revert`
    /// away. An import that had to CHOOSE would be a guess nothing could undo.
    ///
    /// The direction is the committed side because it is the only population known to COMPILE — see
    /// the `import` module docs for why neither `rev` nor `updatedAt` can order the two stores.
    #[test]
    fn a_disagreement_becomes_two_versions_rather_than_a_decision() {
        let c = store();
        let rep = import(&c, &[r("a.rs", "committed")], &[r("a.rs", "runtime")], "import").unwrap();
        assert_eq!(rep.disagreed, 1);
        assert_eq!(get(&c, "a.rs").unwrap().unwrap()["code"], "committed", "the compiling copy is current");
        assert_eq!(revs(&c, "a.rs").unwrap(), vec![2, 1]);
        revert(&c, "a.rs", 1, "me").unwrap();
        assert_eq!(get(&c, "a.rs").unwrap().unwrap()["code"], "runtime", "…and the other side is one revert away");
    }

    /// Identical content is ONE version. Key ORDER must not read as a difference: `preserve_order` is on
    /// in this workspace, so a promoted record and its runtime twin routinely differ only in key order,
    /// and comparing `Value`s directly would import every one of them as a spurious disagreement.
    #[test]
    fn agreement_is_one_version_and_key_order_is_not_a_disagreement() {
        let c = store();
        let a = json!({ "id": "a.rs", "name": "a", "code": "x" });
        let b = json!({ "code": "x", "id": "a.rs", "name": "a" });
        let rep = import(&c, &[a], &[b], "import").unwrap();
        assert_eq!(rep.agreed, 1, "same content, different key order");
        assert_eq!(rep.disagreed, 0);
        assert_eq!(revs(&c, "a.rs").unwrap(), vec![1]);
    }

    /// The 1,123 committed-only records — the crate modules the app's library never had — import onto
    /// `main`. The 804 runtime-only ones do NOT: they are the packaged-seed frontend population plus
    /// whatever other branches' records the shared runtime store was holding, and `main` is what the
    /// export writes into `graph/records/`. They land on `RUNTIME_LANE`, reachable and landable.
    #[test]
    fn a_committed_only_record_lands_on_main_and_a_runtime_only_one_lands_on_a_lane() {
        let c = store();
        let rep = import(&c, &[r("only-committed.rs", "c")], &[r("only-runtime.rs", "r")], "import").unwrap();
        assert_eq!((rep.committed_only, rep.runtime_only), (1, 1));
        assert!(get(&c, "only-committed.rs").unwrap().is_some());
        assert!(get(&c, "only-runtime.rs").unwrap().is_none(), "main must not adopt a runtime-only id");
        assert_eq!(
            get_in(&c, RUNTIME_LANE, "only-runtime.rs").unwrap().unwrap()["code"],
            "r",
            "…but it is on the lane, not lost"
        );
        land(&c, RUNTIME_LANE, "me").unwrap();
        assert!(get(&c, "only-runtime.rs").unwrap().is_some(), "and landing it is a decision somebody makes");
    }

    /// THE GUARD, and the one that would have caught the `error[E0432]` this rule was rewritten for.
    ///
    /// It asserts the PROPERTY rather than the rule: whatever the precedence ends up being, exporting
    /// `main` straight after an import must reproduce the committed store exactly — that store is what
    /// the build compiles, so any id where it does not is a build the migration silently changed.
    ///
    /// The bite is `shared.rs`: present in both, DIFFERENT in each, and the committed body is the one
    /// that has to survive. Taking the runtime side (the rule this replaced) fails this test on that id.
    #[test]
    fn export_of_main_reproduces_the_committed_store() {
        let c = store();
        let committed = vec![
            r("shared.rs", "pub use crate::ImportSpec;"),
            r("committed-only.rs", "fn c() {}"),
            r("agreed.rs", "fn a() {}"),
        ];
        let runtime = vec![
            r("shared.rs", "// the stale runtime copy, missing the re-export"),
            // Same content as the committed `agreed.rs`, keys in a different ORDER — the shape that
            // rewrote 16 records on every export while `same()` correctly called them equal.
            json!({ "code": "fn a() {}", "tech": "rust", "name": "agreed.rs", "id": "agreed.rs" }),
            r("frontend.ts", "export const x = 1;"),
        ];
        import(&c, &committed, &runtime, "import").unwrap();

        // Compared as SERIALIZED BYTES, not as `Value`s. `preserve_order` makes a body an `IndexMap`,
        // whose `PartialEq` ignores key order — so a `Value` comparison calls two records equal while
        // the files they export to differ, which is exactly the drift this test exists to see.
        let bytes = |v: &Value| serde_json::to_string(v).unwrap();
        let doc = document(&c).unwrap();
        let got: std::collections::BTreeMap<String, String> = doc["implementations"]
            .as_array()
            .unwrap()
            .iter()
            .map(|r| (r["id"].as_str().unwrap().to_string(), bytes(&body_of(r))))
            .collect();
        let want: std::collections::BTreeMap<String, String> =
            committed.iter().map(|r| (r["id"].as_str().unwrap().to_string(), bytes(&body_of(r)))).collect();

        assert_eq!(got.keys().collect::<Vec<_>>(), want.keys().collect::<Vec<_>>(), "main holds exactly the committed ids");
        for (id, body) in &want {
            assert_eq!(got.get(id), Some(body), "'{id}' exports the committed body, byte for byte");
        }
        assert!(!got.contains_key("frontend.ts"), "a runtime-only record must not reach the export");

        // EDGES are records too, and the first cut of this migration exported `"edges": []` over all
        // of them because nothing imported the tier. The invariant covers both tiers or it covers the
        // half that happened to be looked at.
        let c_edges = vec![e("spans-two-crates", &["a.rs", "b.rs"])];
        let r_edges = vec![e("spans-two-crates", &["a.rs"]), e("runtime-only-edge", &["x.ts"])];
        import_edges(&c, &c_edges, &r_edges, "import").unwrap();
        let doc = document(&c).unwrap();
        let edges: std::collections::BTreeMap<String, String> = doc["edges"]
            .as_array()
            .unwrap()
            .iter()
            .map(|r| (r["id"].as_str().unwrap().to_string(), bytes(&body_of(r))))
            .collect();
        assert_eq!(edges.keys().collect::<Vec<_>>(), vec!["spans-two-crates"], "main holds the committed edges");
        assert_eq!(edges["spans-two-crates"], bytes(&body_of(&c_edges[0])), "and the committed edge body");
        assert_eq!(
            doc["implementations"].as_array().unwrap().len(),
            3,
            "importing edges must not disturb the implementation tier"
        );
    }

    /// A TOMBSTONE carries the tier too. The column's `DEFAULT 'impl'` made removing an edge reclassify
    /// it, so the record came back as an implementation the moment anything reverted the removal — and
    /// a build would then try to compile a relationship.
    #[test]
    fn removing_an_edge_keeps_it_an_edge() {
        let c = store();
        import_edges(&c, &[e("spans", &["a.rs"])], &[], "import").unwrap();
        remove(&c, "spans", "me", Some("retired")).unwrap();
        assert_eq!(tier_in(&c, MAIN, "spans").unwrap(), TIER_EDGE, "the tombstone is on the edge tier");
        revert(&c, "spans", 1, "me").unwrap();
        let doc = document(&c).unwrap();
        assert_eq!(doc["edges"].as_array().unwrap().len(), 1, "and it comes back as an edge");
        assert_eq!(doc["implementations"].as_array().unwrap().len(), 0);
    }

    /// An edge is a record on `TIER_EDGE`: same precedence, same lane rule, same recoverability. The
    /// tier is the ONLY difference, and mixing the two tiers into one population would let an edge id
    /// and a module id collide.
    #[test]
    fn an_edge_is_a_record_on_its_own_tier() {
        let c = store();
        let rep = import_edges(&c, &[e("both", &["a.rs"])], &[e("both", &["b.rs"]), e("rt", &["c.rs"])], "import").unwrap();
        assert_eq!((rep.disagreed, rep.runtime_only), (1, 1));
        let doc = document(&c).unwrap();
        assert_eq!(doc["edges"].as_array().unwrap().len(), 1, "the runtime-only edge is on the lane");
        assert_eq!(doc["implementations"].as_array().unwrap().len(), 0, "and nothing landed as an implementation");
        // one revert away, exactly as for an implementation
        revert(&c, "both", 1, "me").unwrap();
        assert_eq!(document(&c).unwrap()["edges"][0]["members"][0], "b.rs");
    }

    /// Idempotent by id. Re-running must not double every history — an import that could only be run
    /// once safely is one nobody can re-run after fixing an input.
    #[test]
    fn importing_twice_changes_nothing() {
        let c = store();
        import(&c, &[r("a.rs", "c")], &[r("a.rs", "r")], "import").unwrap();
        let before = revs(&c, "a.rs").unwrap();
        let rep = import(&c, &[r("a.rs", "c")], &[r("a.rs", "r")], "import").unwrap();
        assert_eq!(rep.skipped, 1);
        assert_eq!(rep.revs_written, 0);
        assert_eq!(revs(&c, "a.rs").unwrap(), before);
    }

    /// The ledger's own fields come OUT of the body. Leaving them in would mean two answers to "what
    /// rev is this", which drift the moment anything writes.
    #[test]
    fn the_ledgers_fields_are_stripped_from_the_body() {
        let c = store();
        let rec = json!({ "id": "a.rs", "code": "x", "rev": 9, "updatedAt": "then",
                          "updatedBy": "someone", "history": [{"rev": 1}], "build": {"verdict": "pass"} });
        import(&c, &[], &[rec], "import").unwrap();
        let got = get_in(&c, RUNTIME_LANE, "a.rs").unwrap().unwrap();
        for k in ["rev", "updatedAt", "updatedBy", "history", "build"] {
            assert!(got.get(k).is_none(), "`{k}` belongs to the ledger now: {got}");
        }
        assert_eq!(got["code"], "x", "…and the content is untouched");
    }

    /// Pre-migration history is kept as PROVENANCE, not as revisions. The old format pruned content
    /// from all but the newest entry (405 of 2,313 carry `prevSrc`), so importing them as revs would
    /// create versions `revert` cannot restore — which is worse than not having them.
    #[test]
    fn legacy_history_is_preserved_but_is_not_a_revision() {
        let c = store();
        let rec = json!({ "id": "a.rs", "code": "now", "history": [
            { "rev": 1, "at": "t1", "by": "someone", "changed": ["code"] },
            { "rev": 2, "at": "t2", "by": "someone", "changed": ["code"], "prevSrc": "before" },
        ]});
        let rep = import(&c, &[], &[rec], "import").unwrap();
        assert_eq!(rep.legacy_entries, 2);

        let kept = legacy_history(&c, "a.rs").unwrap();
        assert_eq!(kept.len(), 2, "both entries readable, verbatim");
        assert_eq!(kept[1]["prevSrc"], "before");

        // …and the LEDGER starts clean at rev 1: no version anyone can be sent back to and not arrive.
        // On `RUNTIME_LANE`, since this record is runtime-only — legacy history is keyed by id and
        // rides along either way.
        assert_eq!(head_rev_in(&c, RUNTIME_LANE, "a.rs").unwrap(), 1);
    }

    /// `body_of` is the projection the import applies — pinned separately because the CLI reuses it.
    #[test]
    fn body_of_keeps_content_and_drops_bookkeeping() {
        let got = body_of(&json!({ "id": "a", "code": "c", "rev": 3, "history": [] }));
        assert_eq!(got, json!({ "id": "a", "code": "c" }));
    }
}

mod document_tests {
    use super::*;
    use crate::{document, sync_document, TIER_EDGE, TIER_IMPL};

    fn doc(impls: Vec<Value>, edges: Vec<Value>) -> Value {
        json!({ "version": 1, "implementations": impls, "edges": edges })
    }
    fn i(id: &str, code: &str) -> Value { json!({ "id": id, "code": code, "tech": "rust" }) }
    fn e(id: &str) -> Value { json!({ "id": id, "members": ["a.rs", "b.rs"] }) }

    /// THE PROPERTY EVERY EXISTING WRITE PATH DEPENDS ON. `bsc graph` mutates the whole document and
    /// calls `save`; if that appended a version per record, a one-record edit would put thousands of
    /// revisions in the ledger and every one would say "something, somewhere, changed". History that
    /// cannot say WHAT moved is not history you can revert with.
    #[test]
    fn a_save_writes_only_the_records_that_actually_moved() {
        let c = store();
        let d = doc(vec![i("a.rs", "1"), i("b.rs", "2"), i("c.rs", "3")], vec![]);
        let first = sync_document(&c, &d, "me", None).unwrap();
        assert_eq!((first.added, first.changed, first.unchanged), (3, 0, 0));

        // Re-saving an unchanged document must write NOTHING.
        let again = sync_document(&c, &d, "me", None).unwrap();
        assert_eq!((again.added, again.changed, again.unchanged), (0, 0, 3));
        assert_eq!(rev_count(&c).unwrap(), 3, "no new versions for an unchanged save");

        // One record moves ⇒ exactly one new version.
        let moved = doc(vec![i("a.rs", "1"), i("b.rs", "CHANGED"), i("c.rs", "3")], vec![]);
        let third = sync_document(&c, &moved, "me", None).unwrap();
        assert_eq!((third.added, third.changed, third.unchanged), (0, 1, 2));
        assert_eq!(rev_count(&c).unwrap(), 4);
        assert_eq!(revs(&c, "b.rs").unwrap(), vec![2, 1]);
        assert_eq!(revs(&c, "a.rs").unwrap(), vec![1], "an untouched record gains no version");
    }

    /// Key order is not a change. `preserve_order` is on here, so a document that merely round-tripped
    /// through a map would otherwise read as every record having moved — which is the same failure as
    /// above, arrived at by a different route.
    #[test]
    fn a_reordered_body_is_not_a_change() {
        let c = store();
        sync_document(&c, &doc(vec![json!({"id":"a.rs","code":"1","tech":"rust"})], vec![]), "me", None).unwrap();
        let s = sync_document(&c, &doc(vec![json!({"tech":"rust","code":"1","id":"a.rs"})], vec![]), "me", None).unwrap();
        assert_eq!(s.unchanged, 1);
        assert_eq!(rev_count(&c).unwrap(), 1);
    }

    /// A record the document no longer carries is TOMBSTONED, not deleted — `impl remove` losing a
    /// record permanently is what this replaces.
    #[test]
    fn a_record_dropped_from_the_document_is_tombstoned_and_recoverable() {
        let c = store();
        sync_document(&c, &doc(vec![i("a.rs", "1"), i("b.rs", "2")], vec![]), "me", None).unwrap();
        let s = sync_document(&c, &doc(vec![i("a.rs", "1")], vec![]), "me", None).unwrap();
        assert_eq!(s.removed, 1);
        assert!(get(&c, "b.rs").unwrap().is_none());
        revert(&c, "b.rs", 1, "me").unwrap();
        assert_eq!(get(&c, "b.rs").unwrap().unwrap()["code"], "2", "still recoverable");
    }

    /// The round trip every reader depends on: what `document` returns must be what `sync_document`
    /// was given, tier for tier. An EDGE is a record of a different tier, not of a different store.
    #[test]
    fn the_document_round_trips_both_tiers() {
        let c = store();
        let d = doc(vec![i("a.rs", "1"), i("b.rs", "2")], vec![e("edge-1")]);
        sync_document(&c, &d, "me", None).unwrap();

        let back = document(&c).unwrap();
        assert_eq!(back["implementations"].as_array().unwrap().len(), 2);
        assert_eq!(back["edges"].as_array().unwrap().len(), 1);
        assert_eq!(back["edges"][0]["id"], "edge-1");
        assert_eq!(back["edges"][0]["members"], json!(["a.rs", "b.rs"]));

        // …and the tiers do not leak into each other.
        let impls: i64 = c.query_row("SELECT COUNT(*) FROM records WHERE tier = ?1", [TIER_IMPL], |r| r.get(0)).unwrap();
        let edges: i64 = c.query_row("SELECT COUNT(*) FROM records WHERE tier = ?1", [TIER_EDGE], |r| r.get(0)).unwrap();
        assert_eq!((impls, edges), (2, 1));
    }
}

mod lane_tests {
    use super::*;
    use crate::{get_in, head_rev, land, lane_changes, lane_conflicts, lanes, put_lane, rebase_record, remove_in, MAIN};

    fn seed(c: &Connection) {
        for id in ["a.rs", "b.rs", "c.rs"] {
            put(c, id, &json!({"id": id, "code": "main"}), "main", None, None).unwrap();
        }
    }

    /// COPY-ON-WRITE. A lane holds rows only for what it writes — the answer to "does a branch
    /// duplicate the store". Measured over this repo's last 40 merges, a slice touches a median of 4
    /// records; a lane is those 4 rows and nothing else.
    #[test]
    fn a_lane_holds_only_what_it_wrote_and_reads_through_for_the_rest() {
        let c = store();
        seed(&c);
        put_lane(&c, "my-slice", "a.rs", &json!({"id":"a.rs","code":"mine"}), "me", None).unwrap();

        let rows: i64 = c
            .query_row("SELECT COUNT(*) FROM record_revs WHERE lane = 'my-slice'", [], |r| r.get(0))
            .unwrap();
        assert_eq!(rows, 1, "one write ⇒ one row, not a copy of the store");

        assert_eq!(get_in(&c, "my-slice", "a.rs").unwrap().unwrap()["code"], "mine", "my own version");
        assert_eq!(get_in(&c, "my-slice", "b.rs").unwrap().unwrap()["code"], "main", "…and main for the rest");
    }

    /// The isolation git branches never gave records: another session cannot see work in progress.
    #[test]
    fn a_lanes_work_is_invisible_to_main_and_to_other_lanes() {
        let c = store();
        seed(&c);
        put_lane(&c, "mine", "a.rs", &json!({"id":"a.rs","code":"WIP"}), "me", None).unwrap();

        assert_eq!(get(&c, "a.rs").unwrap().unwrap()["code"], "main", "main is untouched");
        assert_eq!(get_in(&c, "theirs", "a.rs").unwrap().unwrap()["code"], "main", "another lane sees main");
        let live: i64 = c.query_row("SELECT COUNT(*) FROM records", [], |r| r.get(0)).unwrap();
        assert_eq!(live, 3, "the landed graph still has exactly its three records");
    }

    /// Landing is ONE transaction over the whole slice — half a slice on main is a state nobody asked
    /// for and nobody is watching.
    #[test]
    fn landing_applies_the_whole_lane_and_main_moves_once_per_record() {
        let c = store();
        seed(&c);
        put_lane(&c, "slice", "a.rs", &json!({"id":"a.rs","code":"new-a"}), "me", None).unwrap();
        put_lane(&c, "slice", "b.rs", &json!({"id":"b.rs","code":"new-b"}), "me", None).unwrap();

        let out = land(&c, "slice", "reviewer").unwrap();
        assert_eq!((out.applied, out.removed, out.conflicts.len()), (2, 0, 0));
        assert_eq!(get(&c, "a.rs").unwrap().unwrap()["code"], "new-a");
        assert_eq!(get(&c, "b.rs").unwrap().unwrap()["code"], "new-b");
        assert_eq!(head_rev(&c, "a.rs").unwrap(), 2, "one landing ⇒ one new main rev");
        assert_eq!(head_rev(&c, "c.rs").unwrap(), 1, "an untouched record does not move");
    }

    /// TWO LANES ON DIFFERENT RECORDS BOTH LAND. This is the property the whole migration is for — it
    /// is what a 27 MB single file could never give, and what the per-record split bought and the
    /// database preserves.
    #[test]
    fn two_lanes_touching_different_records_both_land_clean() {
        let c = store();
        seed(&c);
        put_lane(&c, "one", "a.rs", &json!({"id":"a.rs","code":"from-one"}), "me", None).unwrap();
        put_lane(&c, "two", "b.rs", &json!({"id":"b.rs","code":"from-two"}), "you", None).unwrap();

        assert!(land(&c, "one", "rev").unwrap().conflicts.is_empty());
        assert!(land(&c, "two", "rev").unwrap().conflicts.is_empty(), "the second lane is unaffected");
        assert_eq!(get(&c, "a.rs").unwrap().unwrap()["code"], "from-one");
        assert_eq!(get(&c, "b.rs").unwrap().unwrap()["code"], "from-two");
    }

    /// A CONFLICT IS ONE RECORD, named, with base/ours/theirs all still readable — not a file with
    /// markers in it. And nothing lands until it is decided: a partial landing is the failure mode
    /// this refuses.
    #[test]
    fn a_record_both_sides_changed_conflicts_and_blocks_the_whole_landing() {
        let c = store();
        seed(&c);
        put_lane(&c, "slice", "a.rs", &json!({"id":"a.rs","code":"mine"}), "me", None).unwrap();
        put_lane(&c, "slice", "b.rs", &json!({"id":"b.rs","code":"also-mine"}), "me", None).unwrap();
        // …meanwhile main moves under it.
        put(&c, "a.rs", &json!({"id":"a.rs","code":"theirs"}), "someone else", None, None).unwrap();

        let conflicts = lane_conflicts(&c, "slice").unwrap();
        assert_eq!(conflicts.len(), 1);
        assert_eq!(conflicts[0].id, "a.rs");
        assert_eq!((conflicts[0].base_rev, conflicts[0].main_rev), (1, 2), "base and ours, both known");

        let out = land(&c, "slice", "rev").unwrap();
        assert_eq!(out.conflicts, vec!["a.rs".to_string()]);
        assert_eq!((out.applied, out.removed), (0, 0), "NOTHING lands while one record is contested");
        assert_eq!(get(&c, "b.rs").unwrap().unwrap()["code"], "main", "…including the clean one");

        // All three sides are still readable, which is what makes the decision possible at all.
        assert_eq!(get(&c, "a.rs").unwrap().unwrap()["code"], "theirs");
        assert_eq!(get_in(&c, "slice", "a.rs").unwrap().unwrap()["code"], "mine");
    }

    /// Resolving = re-basing onto what main says now. It does not merge: a three-way merge of two
    /// bodies is a judgement, and the store's job is to keep both readable while someone makes it.
    #[test]
    fn rebasing_a_contested_record_lets_the_lane_land() {
        let c = store();
        seed(&c);
        put_lane(&c, "slice", "a.rs", &json!({"id":"a.rs","code":"mine"}), "me", None).unwrap();
        put(&c, "a.rs", &json!({"id":"a.rs","code":"theirs"}), "them", None, None).unwrap();
        assert_eq!(lane_conflicts(&c, "slice").unwrap().len(), 1);

        rebase_record(&c, "slice", "a.rs", "me").unwrap();
        assert!(lane_conflicts(&c, "slice").unwrap().is_empty(), "the base now matches main");

        let out = land(&c, "slice", "rev").unwrap();
        assert_eq!(out.applied, 1);
        assert_eq!(get(&c, "a.rs").unwrap().unwrap()["code"], "mine");
        // …and what main had is still there, one revert away.
        assert_eq!(revs(&c, "a.rs").unwrap(), vec![3, 2, 1]);
    }

    /// A lane can REMOVE a record, and landing carries the tombstone across.
    #[test]
    fn a_lane_can_remove_a_record_and_landing_carries_it() {
        let c = store();
        seed(&c);
        remove_in(&c, "slice", "a.rs", "me", None).unwrap();
        assert!(get_in(&c, "slice", "a.rs").unwrap().is_none(), "gone in the lane");
        assert!(get(&c, "a.rs").unwrap().is_some(), "…still on main until it lands");

        let out = land(&c, "slice", "rev").unwrap();
        assert_eq!((out.applied, out.removed), (0, 1));
        assert!(get(&c, "a.rs").unwrap().is_none());
        revert(&c, "a.rs", 1, "me").unwrap();
        assert!(get(&c, "a.rs").unwrap().is_some(), "and still recoverable after landing");
    }

    /// `main` is the landed graph, not a lane — comparing it against itself is a question with no
    /// meaning, and answering it would invite landing main onto main.
    #[test]
    fn main_is_not_a_lane() {
        let c = store();
        seed(&c);
        assert!(lane_changes(&c, MAIN).is_err());
        assert!(land(&c, MAIN, "me").is_err());
    }

    /// Landing does not delete the lane: what was landed and from where stays answerable.
    #[test]
    fn a_landed_lane_keeps_its_rows() {
        let c = store();
        seed(&c);
        put_lane(&c, "slice", "a.rs", &json!({"id":"a.rs","code":"x"}), "me", None).unwrap();
        land(&c, "slice", "rev").unwrap();
        let named: Vec<String> = lanes(&c).unwrap().into_iter().map(|(l, _)| l).collect();
        assert!(named.contains(&"slice".to_string()), "{named:?}");
    }
}

mod export_tests {
    use super::*;
    use crate::{document_in, put, put_lane, remove_in, MAIN};

    fn seed(c: &Connection) {
        for id in ["a.rs", "b.rs"] {
            put(c, id, &json!({"id": id, "code": "main"}), "main", None, None).unwrap();
        }
    }
    fn ids(doc: &Value) -> Vec<String> {
        let mut v: Vec<String> = doc["implementations"].as_array().unwrap().iter()
            .map(|r| r["id"].as_str().unwrap().to_string()).collect();
        v.sort(); v
    }

    /// THE EXPORT'S WHOLE JOB: a worktree bound to a lane must build ITS records, not main's — its own
    /// version of what it touched, and main's for everything else.
    #[test]
    fn a_lane_exports_its_own_version_over_mains() {
        let c = store();
        seed(&c);
        put_lane(&c, "slice", "a.rs", &json!({"id":"a.rs","code":"mine"}), "me", None).unwrap();

        let d = document_in(&c, "slice").unwrap();
        assert_eq!(ids(&d), vec!["a.rs", "b.rs"], "both records, exactly once each");
        let a = d["implementations"].as_array().unwrap().iter()
            .find(|r| r["id"] == "a.rs").unwrap();
        let b = d["implementations"].as_array().unwrap().iter()
            .find(|r| r["id"] == "b.rs").unwrap();
        assert_eq!(a["code"], "mine", "the lane's own version");
        assert_eq!(b["code"], "main", "…and main's for what it did not touch");

        // …while main's own export is untouched by the lane.
        assert_eq!(document_in(&c, MAIN).unwrap()["implementations"].as_array().unwrap().len(), 2);
        let ma = document_in(&c, MAIN).unwrap()["implementations"].as_array().unwrap()
            .iter().find(|r| r["id"] == "a.rs").unwrap().clone();
        assert_eq!(ma["code"], "main");
    }

    /// A record the lane REMOVED must not reappear from main. Without the tombstone check the union
    /// would quietly resurrect it, and the build would compile a module the author deleted.
    #[test]
    fn a_record_the_lane_removed_does_not_come_back_from_main() {
        let c = store();
        seed(&c);
        remove_in(&c, "slice", "a.rs", "me", None).unwrap();
        assert_eq!(ids(&document_in(&c, "slice").unwrap()), vec!["b.rs"]);
        assert_eq!(ids(&document_in(&c, MAIN).unwrap()), vec!["a.rs", "b.rs"], "main still has it");
    }

    /// A lane that has written nothing exports exactly main — otherwise every fresh lane would need a
    /// copy before it could build.
    #[test]
    fn an_untouched_lane_exports_main_unchanged() {
        let c = store();
        seed(&c);
        assert_eq!(ids(&document_in(&c, "brand-new").unwrap()), ids(&document_in(&c, MAIN).unwrap()));
    }

    /// Edges travel with the export, on their own tier — a build that lost them would stop compiling
    /// the `[[test]]` targets they carry.
    #[test]
    fn edges_are_exported_on_their_own_tier() {
        let c = store();
        seed(&c);
        put_in(&c, MAIN, "e1", &json!({"id":"e1","members":["a.rs","b.rs"]}),
               Write::by("me").tier(TIER_EDGE)).unwrap();
        let d = document_in(&c, "slice").unwrap();
        assert_eq!(d["edges"].as_array().unwrap().len(), 1);
        assert_eq!(d["implementations"].as_array().unwrap().len(), 2, "edges do not leak into impls");
    }
}
